import type {
  DocEnumeration,
  DocEvent,
  DocField,
  DocFunction,
  DocStructure,
  DocSystem,
} from "./model.js";
import {
  fieldType,
  mapType,
  safeMemberName,
  safeParamName,
  type TypeContext,
} from "./typemap.js";

export interface EmitResult {
  files: Record<string, string>;
  stats: {
    systems: number;
    functions: number;
    events: number;
    enums: number;
    structures: number;
    objects: number;
    protectedFunctions: number;
  };
}

const HEADER =
  "// GENERATED by wow-declarations-toolkit. Do not edit by hand.\n" +
  "// Source: Gethe/wow-ui-source Blizzard_APIDocumentationGenerated.\n";

function isEnumeration(t: unknown): t is DocEnumeration {
  return !!t && (t as DocEnumeration).Type === "Enumeration";
}
function isStructure(t: unknown): t is DocStructure {
  return !!t && (t as DocStructure).Type === "Structure";
}

/** Build the enum/structure registries every signature resolves against. */
export function buildContext(systems: DocSystem[]): {
  ctx: TypeContext;
  enums: DocEnumeration[];
  structures: DocStructure[];
} {
  const enumMap = new Map<string, DocEnumeration>();
  const structMap = new Map<string, DocStructure>();
  for (const system of systems) {
    for (const table of system.Tables ?? []) {
      if (isEnumeration(table) && !enumMap.has(table.Name)) enumMap.set(table.Name, table);
      else if (isStructure(table) && !structMap.has(table.Name)) structMap.set(table.Name, table);
    }
  }
  const enums = [...enumMap.values()].sort((a, b) => a.Name.localeCompare(b.Name));
  const structures = [...structMap.values()].sort((a, b) => a.Name.localeCompare(b.Name));
  const ctx: TypeContext = {
    enums: new Set(enumMap.keys()),
    structures: new Set([...structMap.keys()].filter((n) => !enumMap.has(n))),
    objects: new Set<string>(),
  };
  return { ctx, enums, structures };
}

/** Argument list, keeping TS's "optional params trail required ones" rule. */
export function emitParams(args: DocField[], ctx: TypeContext): string {
  const seen = new Map<string, number>();
  return args
    .map((arg, index) => {
      let name = safeParamName(arg.Name || `arg${index + 1}`);
      const count = seen.get(name) ?? 0;
      seen.set(name, count + 1);
      if (count > 0) name = `${name}_${count}`;
      const type = mapType(arg, ctx);
      // Optional only when every later argument is also nilable, otherwise TS
      // rejects the signature; fall back to a `| undefined` union.
      const restOptional = args.slice(index + 1).every((a) => a.Nilable);
      if (arg.Nilable && restOptional) return `${name}?: ${type}`;
      if (arg.Nilable) return `${name}: ${type} | undefined`;
      return `${name}: ${type}`;
    })
    .join(", ");
}

/** Return type: void / T / LuaMultiReturn<[...]> with nilable folded in. */
export function emitReturns(returns: DocField[], ctx: TypeContext): string {
  if (returns.length === 0) return "void";
  if (returns.length === 1) {
    const t = mapType(returns[0], ctx);
    return returns[0].Nilable ? `${t} | undefined` : t;
  }
  const members = returns.map((ret, index) => {
    const label = safeParamName(ret.Name || `value${index + 1}`);
    const t = mapType(ret, ctx);
    // A tuple's optional elements must trail, same as a parameter list.
    const restOptional = returns.slice(index + 1).every((r) => r.Nilable);
    if (ret.Nilable && restOptional) return `${label}?: ${t}`;
    if (ret.Nilable) return `${label}: ${t} | undefined`;
    return `${label}: ${t}`;
  });
  return `LuaMultiReturn<[${members.join(", ")}]>`;
}

export function emitFunction(fn: DocFunction, ctx: TypeContext, indent: string): string {
  const params = emitParams(fn.Arguments ?? [], ctx);
  const returns = emitReturns(fn.Returns ?? [], ctx);
  const lines: string[] = [];
  const notes: string[] = [];
  if (fn.HasRestrictions) {
    // Protected: the client only honours the call from secure execution. Kept
    // in the type surface so it type-checks, flagged so the TSTL guard and a
    // reader both see the restriction at the call site.
    notes.push("@protected Only callable from secure/hardware-triggered code.");
  }
  if (fn.Documentation?.length) notes.push(...fn.Documentation);
  if (notes.length) {
    lines.push(`${indent}/**`);
    for (const note of notes) lines.push(`${indent} * ${note}`);
    lines.push(`${indent} */`);
  }
  lines.push(`${indent}function ${fn.Name}(${params}): ${returns};`);
  return lines.join("\n");
}

function emitEnums(enums: DocEnumeration[]): string {
  const body = enums
    .map((e) => {
      const members = e.Fields.map(
        (f) => `    ${safeMemberName(f.Name)} = ${f.EnumValue ?? 0},`,
      ).join("\n");
      return `  enum ${e.Name} {\n${members}\n  }`;
    })
    .join("\n\n");
  return `${HEADER}\ndeclare namespace Enum {\n${body}\n}\n`;
}

function emitStructures(structures: DocStructure[], ctx: TypeContext): string {
  const body = structures
    .map((s) => {
      const fields = s.Fields.map((f) => {
        const optional = f.Nilable ? "?" : "";
        const type = f.Nilable ? mapType(f, ctx) : fieldType(f, ctx);
        return `    ${safeMemberName(f.Name)}${optional}: ${type};`;
      }).join("\n");
      return `  interface ${s.Name} {\n${fields}\n  }`;
    })
    .join("\n\n");
  return `${HEADER}\ndeclare namespace WowStruct {\n${body}\n}\n`;
}

function emitObjects(objects: Set<string>): string {
  const names = [...objects].sort();
  const body = names
    .map(
      (n) =>
        `  /** Opaque WoW handle. Nominal placeholder; frame methods live in declarations/. */\n` +
        `  interface ${n} { readonly __wowObject: ${JSON.stringify(n)}; }`,
    )
    .join("\n\n");
  return `${HEADER}\ndeclare namespace WowObject {\n${body}\n}\n`;
}

function emitNamespaces(systems: DocSystem[], ctx: TypeContext): string {
  const chunks: string[] = [];
  // Group functions by namespace so a namespace split across doc files merges.
  const byNamespace = new Map<string, DocFunction[]>();
  const globals: DocFunction[] = [];
  for (const system of systems) {
    for (const fn of system.Functions ?? []) {
      if (system.Namespace) {
        const list = byNamespace.get(system.Namespace) ?? [];
        list.push(fn);
        byNamespace.set(system.Namespace, list);
      } else {
        globals.push(fn);
      }
    }
  }
  for (const ns of [...byNamespace.keys()].sort()) {
    const fns = byNamespace.get(ns)!;
    const body = fns.map((fn) => emitFunction(fn, ctx, "  ")).join("\n");
    chunks.push(`declare namespace ${ns} {\n${body}\n}`);
  }
  for (const fn of globals) {
    chunks.push(emitFunction(fn, ctx, "").replace(/^function /m, "declare function "));
  }
  // WoW's C_* functions are dot-called, so TypeScriptToLua must not pass an
  // implicit self; @noSelfInFile marks every function in this file as such.
  return `${HEADER}/** @noSelfInFile */\n\n${chunks.join("\n\n")}\n`;
}

function emitEvents(systems: DocSystem[], ctx: TypeContext): string {
  const events: DocEvent[] = [];
  const seen = new Set<string>();
  for (const system of systems) {
    for (const ev of system.Events ?? []) {
      if (ev.LiteralName && !seen.has(ev.LiteralName)) {
        seen.add(ev.LiteralName);
        events.push(ev);
      }
    }
  }
  events.sort((a, b) => a.LiteralName.localeCompare(b.LiteralName));
  const entries = events
    .map((ev) => {
      const payload = ev.Payload ?? [];
      const members = payload.map((p, i) => {
        const label = safeParamName(p.Name || `arg${i + 1}`);
        const trailing = payload.slice(i + 1).every((q) => q.Nilable);
        const type = mapType(p, ctx);
        if (p.Nilable && trailing) return `${label}?: ${type}`;
        if (p.Nilable) return `${label}: ${type} | undefined`;
        return `${label}: ${type}`;
      });
      return `    ${JSON.stringify(ev.LiteralName)}: [${members.join(", ")}];`;
    })
    .join("\n");
  return (
    `${HEADER}\ndeclare namespace WowEvent {\n` +
    `  interface PayloadMap {\n${entries}\n  }\n` +
    `  type Name = keyof PayloadMap;\n}\n`
  );
}

export function emitRelease(systems: DocSystem[], release: { id: string; version: string; label: string }): EmitResult {
  const { ctx, enums, structures } = buildContext(systems);
  // Namespaces/events must be emitted before objects.d.ts so mapType has
  // recorded every referenced opaque handle in ctx.objects.
  const namespaces = emitNamespaces(systems, ctx);
  const events = emitEvents(systems, ctx);
  const structuresFile = emitStructures(structures, ctx);
  const enumsFile = emitEnums(enums);
  const objectsFile = emitObjects(ctx.objects);

  const index =
    `${HEADER}\n` +
    `// World of Warcraft ${release.label} (${release.version}).\n` +
    `// LuaMultiReturn comes from @typescript-to-lua/language-extensions, which\n` +
    `// tsconfig.${release.id}.json lists in compilerOptions.types.\n\n` +
    `import "./enums";\nimport "./structures";\nimport "./objects";\n` +
    `import "./namespaces";\nimport "./events";\n`;

  let protectedFunctions = 0;
  for (const s of systems) for (const f of s.Functions ?? []) if (f.HasRestrictions) protectedFunctions++;
  let functions = 0;
  for (const s of systems) functions += s.Functions?.length ?? 0;
  let eventCount = 0;
  for (const s of systems) eventCount += s.Events?.length ?? 0;

  return {
    files: {
      "enums.d.ts": enumsFile,
      "structures.d.ts": structuresFile,
      "objects.d.ts": objectsFile,
      "namespaces.d.ts": namespaces,
      "events.d.ts": events,
      "index.d.ts": index,
    },
    stats: {
      systems: systems.length,
      functions,
      events: eventCount,
      enums: enums.length,
      structures: structures.length,
      objects: ctx.objects.size,
      protectedFunctions,
    },
  };
}

/** Fully-qualified names of protected functions, for the TSTL call guard. */
export function collectProtected(systems: DocSystem[]): string[] {
  const names: string[] = [];
  for (const system of systems) {
    for (const fn of system.Functions ?? []) {
      if (fn.HasRestrictions) {
        names.push(system.Namespace ? `${system.Namespace}.${fn.Name}` : fn.Name);
      }
    }
  }
  return names.sort();
}
